    const m = p.module;
    if (p.profileShift * m - (1 + p.clearance) * m + p.rootFillet * m >= -1e-6)
      out.push({ key: "profileShift", level: "error", msg: t("Profilverschiebung zu gro\xDF f\xFCr Kopfspiel und Fu\xDFrundung.") });
    if (p.backlash / 2 >= Math.PI * m / 4) out.push({ key: "backlash", level: "error", msg: t("Flankenspiel zu gro\xDF f\xFCr dieses Modul.") });
    if (out.length) return out;
