    const before = sk.cons.map((c) => c.v);
    const issues2 = this.sketchResolveExprs(sk, scope).map((msg) => ({ level: "error", msg }));
    if (sk.cons.every((c, i) => c.v === before[i])) return issues2;
    const r = solveSketch(sk);
    if (!r.ok) {
      issues2.push({ level: "error", msg: t("Die Skizze l\xE4sst sich mit den neuen Ma\xDFen nicht l\xF6sen.") });
      return issues2;
    }
