    const ans = this.onSketchValue ? await this.onSketchValue(dimTitle(c.t, c.r), c.v ?? measureCon(s.sk, c) ?? 0, c.t === "angle" ? "\xB0" : "mm", c.expr) : null;
    if (!ans) return;
