    this.syncSketch();
    const list2 = conFromSel(s.sk, [...s.sel], type);
    if (!list2) {
      this.hint = t("Diese Beziehung passt nicht zur Auswahl.");
      this.emit("tool");
      return;
    }
    const ok = this.sketchChange(t("Skizze: {name}", { name: CON_LABELS[type] }), (sk) => {
      for (const c of list2) addCon(sk, c.t, c.r, c.t === "fixed" ? { x: ptOf(sk, c.r[0]).x, y: ptOf(sk, c.r[0]).y } : {});
    });
